int parse_facilities(unsigned char *p, struct rose_facilities_struct *facilities) {
    unsigned char length;

    if (!p || !facilities)
        return 0;

    length = *p++;

    if (length == 0)
        return 1;

    while (length > 0) {
        unsigned char type = *p++;

        length--;

        if (type == ROSE_FACILITY_NATIONAL) {
            if (!parse_national_facility(p, facilities))
                return 0;
        } else if (type == ROSE_FACILITY_CCITT) {
            if (!parse_ccitt_facility(p, facilities))
                return 0;
        } else {
            /* Unknown facility type, skip it */
            fprintf(stderr, "Unknown facility type encountered: 0x%x\n", type);
        }

        p += ROSE_FACILITY_SIZE - 1;
        length -= ROSE_FACILITY_SIZE - 1;
    }

    return 1;
}

int parse_facilities(unsigned char *p, struct rose_facilities_struct *facilities) {
    int length = *p++;

    if (length == 0)
        return 1;

    if (length < 2) {
        // Invalid length
        return 0;
    }

    facilities->count = 0;
    facilities->list = NULL;

    while (length > 0) {
        int facility_type = *p++;

        switch (facility_type) {
            case ROSE_FACILITY_NATIONAL:
                if (length < 2) {
                    return 0;
                }
                // Call function to parse national facility
                if (!parse_national_facility(p, facilities)) {
                    return 0;
                }
                break;
            case ROSE_FACILITY_CCITT:
                if (length < 2) {
                    return 0;
                }
                // Call function to parse CCITT facility
                if (!parse_ccitt_facility(p, facilities)) {
                    return 0;
                }
                break;
            default:
                // Unknown facility type, log and continue
                fprintf(stderr, "Unknown facility type: %d\n", facility_type);
                return 0;
        }

        length -= 2;
        p += 1;
    }

    return 1;
}

int parse_facilities(unsigned char *p, struct rose_facilities_struct *facilities) {
    int length = *p++;

    if (length == 0)
        return 1;

    if (length < 2) {
        // Invalid length
        return 0;
    }

    facilities->count = 0;
    facilities->facility = NULL;

    while (length > 0) {
        int type = *p++;
        int code = *p++;
        length -= 2;

        if (length < 0) {
            // Invalid length
            return 0;
        }

        if (type == ROSE_FACILITY_NATIONAL) {
            if (!parse_national_facility(p, code, facilities)) {
                return 0;
            }
        } else if (type == ROSE_FACILITY_CCITT) {
            if (!parse_ccitt_facility(p, code, facilities)) {
                return 0;
            }
        } else {
            // Unknown facility type
            debug_printf("Unknown facility type %d code %d\n", type, code);
        }

        p += length;
        length = 0;
    }

    return 1;
}

int parse_facilities(unsigned char *p, struct rose_facilities_struct *facilities) {
    int length;

    if (!p || !facilities)
        return 0;

    length = *p++;

    if (length == 0)
        return 1;

    if (length % 2 != 0)
        return 0;

    while (length > 0) {
        int type = *p++;
        int length_octets = *p++;

        length -= 2;

        switch (type) {
        case ROSE_FACILITY_NATIONAL:
            if (!parse_national_facility(p, length_octets, facilities))
                return 0;
            break;
        case ROSE_FACILITY_CCITT:
            if (!parse_ccitt_facility(p, length_octets, facilities))
                return 0;
            break;
        default:
            LOG_DEBUG("Unknown facility type 0x%x", type);
            break;
        }

        if (length_octets > length)
            return 0;

        p += length_octets;
        length -= length_octets;
    }

    return 1;
}

int parse_facilities(unsigned char *p, struct rose_facilities_struct *facilities) {
    int length;

    length = *p++;

    if (length == 0)
        return 1;

    if (length < 2)
        return 0;

    while (length > 0) {
        int facility_type, facility_length;

        facility_type = (*p << 8) | *(p + 1);
        p += 2;
        facility_length = *p++;

        if (facility_length > length - 2)
            return 0;

        switch (facility_type) {
        case ROSE_FACILITY_NATIONAL:
            if (!parse_national_facility(p, facilities))
                return 0;
            break;
        case ROSE_FACILITY_CCITT:
            if (!parse_ccitt_facility(p, facilities))
                return 0;
            break;
        default:
            printk(KERN_DEBUG "Unknown ROSE facility type: %04X\n", facility_type);
            break;
        }

        p += facility_length;
        length -= 2 + facility_length;
    }

    return 1;
}
